#include <stdio.h>
int main(void) {
    char river[] = "___";
    const int width = (int)sizeof river - 1;
    int wet = 0;
    puts("收据背面，开河。");
    for (int i = 0; i < width; ++i) {
        river[i] = '~';
        puts(river);
    }
    for (int i = 0; i < width; ++i) {
        wet += river[i] == '~';
    }
    printf("河里住进了 %d 滴雨。\n", wet);
    if (wet == width) {
        puts("账目已满，改记水声。");
    }
    return 0;
}

